"Мяч — любимый снаряд игроков. Давай узнаем, что с ним можно делать. Нажимай на карточки.": "To‘p — o‘yinchilarning sevimli jihozi. Keling, u bilan nima qilish mumkinligini bilib olaylik. Kartochkalarni bos.",
"Надевай удобную обувь, завязывай шнурки и слушай учителя.": "Qulay oyoq kiyim kiy, bog‘ichlarni bog‘la va o‘qituvchini tingla.",
"Наклоны входят в разминку. Они разогревают спину и ноги.": "Engashishlar qizdirinishga kiradi. Ular orqa va oyoqlarni isitadi.",
"Начинают бег по сигналу. Время засекают секундомером.": "Yugurishni ishora bo‘yicha boshlaydilar. Vaqtni sekundomer bilan o‘lchaydilar.",
"Объяснять, зачем нужна разминка, и соблюдать правила безопасности": "Qizdirinish nega kerakligini tushuntirish va xavfsizlik qoidalariga rioya qilish",
"Перед занятием тело нужно подготовить. Давай узнаем, как разминаться и как не получить травму. Нажимай на карточки.": "Mashg‘ulotdan oldin tanani tayyorlash kerak. Qanday qizdirinish va jarohat olmaslikni bilib olaylik. Kartochkalarni bos.",
"Перетягивание каната — две команды тянут канат в разные стороны.": "Arqon tortish — ikki jamoa arqonni turli tomonga tortadi.",
"По гимнастической скамейке ходят, держа спину прямо и руки в стороны.": "Gimnastika o‘rindig‘ida belni tik tutib, qo‘llarni yon tomonga cho‘zib yuradilar.",
"Победителя нужно поздравить, а проигравшего подбодрить.": "G‘olibni tabriklash, yutqazganni esa ruhlantirish kerak.",
"Поздравляю! Ты узнал про здоровье, разминку, бег и прыжки, гимнастику, игры с мячом, национальные игры и честную командную игру. Теперь можно двигаться и играть каждый день!": "Tabriklayman! Sen salomatlik, qizdirinish, yugurish va sakrash, gimnastika, to‘p o‘yinlari, milliy o‘yinlar va halol jamoaviy o‘yin haqida bilib olding. Endi har kuni harakat qilish va o‘ynash mumkin!",
"Понимать пользу движения и изменения в теле при нагрузке": "Harakatning foydasini va yuklama paytida tanadagi o‘zgarishlarni tushunish",
"После бега мы дышим чаще. Это нормально.": "Yugurgandan keyin biz tez-tez nafas olamiz. Bu normal.",
"После игры полезно попить воды.": "O‘yindan keyin suv ichish foydali.",
"После нагрузки идём спокойно и дышим ровно. Это заминка.": "Yuklamadan keyin tinch yuramiz va tekis nafas olamiz. Bu — tinchlanish.",
"При беге сердце бьётся быстрее, чтобы тело получило больше воздуха.": "Yugurganda yurak tezroq uradi, shunda tana ko‘proq havo oladi.",
"При ведении мяч двигается рядом с игроком.": "To‘pni olib yurganda u o‘yinchining yonida harakatlanadi.",
"При метании замахиваются рукой и бросают предмет в цель.": "Uloqtirishda qo‘lni siltab, narsani nishonga otadilar.",
"При прыжке отталкиваются ногами. Приземляются на мягкие согнутые ноги.": "Sakraganda oyoqlar bilan depsinadilar. Yumshoq bukilgan oyoqlarga qo‘nadilar.",
"Привет! Это Барсик. Движение делает нас сильными и здоровыми. Нажимай на карточки и узнавай, что происходит с телом.": "Salom! Bu Barsik. Harakat bizni kuchli va sog‘lom qiladi. Kartochkalarni bos va tanada nima bo‘lishini bilib ol.",
"Приседания делают ноги сильнее.": "O‘tirib-turishlar oyoqlarni kuchliroq qiladi.",
"Приседания разогревают ноги.": "O‘tirib-turishlar oyoqlarni qizdiradi.",
"Проверим, что ты запомнил. Выбери верный ответ.": "Nimani eslab qolganingni tekshirib ko‘ramiz. To‘g‘ri javobni tanla.",
"Прыжок в длину мерят от линии старта до места приземления.": "Uzunlikka sakrashni start chizig‘idan qo‘nish joyigacha o‘lchaydilar.",
"Различать бег, прыжки и метание и сравнивать результаты": "Yugurish, sakrash va uloqtirishni ajratish hamda natijalarni taqqoslash",
"Разложи карточки по группам. Выбери, к какой группе относится каждая карточка.": "Kartochkalarni guruhlarga ajrat. Har bir kartochka qaysi guruhga tegishli ekanini tanla.",
"Разложи по группам": "Guruhlarga ajrat",
"Разминка согревает мышцы и помогает не получить травму.": "Qizdirinish mushaklarni isitadi va jarohat olmaslikka yordam beradi.",
"Салки, эстафеты с обручем и бег с флажками играют без мяча.": "Quvlashmachoq, halqali estafetalar va bayroqchalar bilan yugurish to‘psiz o‘ynaladi.",
"Секундомер показывает, за сколько секунд ты пробежал.": "Sekundomer necha sekundda yugurganingni ko‘rsatadi.",
"Сохранять равновесие и держать правильную осанку": "Muvozanatni saqlash va to‘g‘ri qomatni tutish",
"Судья следит за правилами и подаёт сигнал свистком.": "Hakam qoidalarni kuzatadi va hushtak bilan ishora beradi.",
