"Готовую работу можно показать на выставке. Рядом пишут название и имя автора.": "Tayyor ishni ko‘rgazmada ko‘rsatish mumkin. Uning yoniga nomi va muallifning ismi yoziladi.",
"Графика — рисунок линиями и штрихами. Рисуют карандашом, углём или пером.": "Grafika — chiziqlar va shtrixlar bilan chizilgan rasm. Qalam, ko‘mir yoki pero bilan chizadilar.",
"Гуашь — густая непрозрачная краска. Акварель — прозрачная краска, её разводят водой.": "Guash — quyuq, shaffof bo‘lmagan bo‘yoq. Akvarel — shaffof bo‘yoq, uni suv bilan suyultiradilar.",
"Декоративно-прикладное искусство — красивые вещи, которыми пользуются: посуда, ковры, вышивка.": "Amaliy bezak san’ati — foydalaniladigan chiroyli buyumlar: idish-tovoq, gilamlar, kashta.",
"Дизайнер придумывает форму вещей: стула, чайника, игрушки или упаковки.": "Dizayner narsalarning shaklini o‘ylab topadi: stul, choynak, o‘yinchoq yoki o‘ramni.",
"Если рисуем то, что запомнили, это рисование по памяти. Если рисуем то, что придумали, это рисование по воображению.": "Esimizda qolganini chizsak, bu xotiradan chizish. O‘ylab topganimizni chizsak, bu tasavvurdan chizish.",
"Живопись — картины, написанные красками. Главное в живописи — цвет.": "Rangtasvir — bo‘yoqlar bilan chizilgan suratlar. Rangtasvirda eng asosiysi — rang.",
"Зимой много белого и голубого, а осенью жёлтого, оранжевого и красного.": "Qishda oq va ko‘k ranglar ko‘p, kuzda esa sariq, to‘q sariq va qizil.",
"Когда мы смотрим на предмет и рисуем его, это рисование по наблюдению.": "Biror narsaga qarab uni chizsak, bu kuzatib chizish.",
