"Красный, оранжевый и жёлтый — тёплые цвета. Они как солнце и огонь.": "Qizil, to‘q sariq va sariq — iliq ranglar. Ular quyosh va olovga o‘xshaydi.",
"Круговыми движениями ладоней скатывают шарик. Так получаются яблоко и колобок.": "Kaftlarning aylanma harakati bilan sharcha yumalatadilar. Shunday qilib olma va kolobok hosil bo‘ladi.",
