"Лепят из пластилина, глины и солёного теста. Глину во время работы смачивают водой.": "Plastilin, loy va tuzli xamirdan shakl yasaydilar. Ish paytida loyni suv bilan ho‘llaydilar.",
"Линия — главный помощник художника. Ею можно нарисовать почти всё. Нажимай на карточки, чтобы узнать, какие бывают линии.": "Chiziq — rassomning asosiy yordamchisi. U bilan deyarli hamma narsani chizish mumkin. Qanday chiziqlar borligini bilish uchun kartochkalarni bos.",
