"Поздравляю! Ты узнал про виды искусства, линии и штрихи, смешивание красок, лепку, узоры, дизайн и архитектуру. Теперь у тебя получится сделать и показать свою работу!": "Tabriklayman! Sen san’at turlari, chiziqlar va shtrixlar, bo‘yoqlarni aralashtirish, shakl yasash, naqshlar, dizayn va me’morchilik haqida bilib olding. Endi o‘z ishingni yasab, ko‘rsata olasan!",
