"Поздравляю! Ты узнал про семью, школу, родной край, карту, город, права, погоду, путешествия, историю и символы Казахстана. Теперь закрепляй знания в играх.": "Tabriklayman! Sen oila, maktab, ona yurt, xarita, shahar, huquqlar, ob-havo, sayohatlar, tarix va Qozog‘iston ramzlari haqida bilib olding. Endi bilimlaringni o‘yinlarda mustahkamla.",
"Познавательный": "Bilim beruvchi",
"Познавательный туризм: едут узнавать новое. Например, в Туркестан к мавзолею Ходжи Ахмеда Ясави.": "Bilim beruvchi turizm: yangi narsalarni bilgani borishadi. Masalan, Turkistonga Xoja Ahmad Yassaviy maqbarasiga.",
