"Праздники нужны, чтобы помнить важные события в истории страны": "Bayramlar mamlakat tarixidagi muhim voqealarni eslab turish uchun kerak",
"При гололёде идут осторожно, маленькими шагами. Он мешает, но обычно не угрожает жизни.": "Muzlaganda ehtiyotkorlik bilan, mayda qadamlar bilan yuriladi. U xalaqit beradi, lekin odatda hayotga xavf solmaydi.",
