"Бабочка откладывает яйца.": "Kapalak tuxum qo‘yadi.",
"Бабочка откладывает яйца. Из яйца выходит гусеница. Гусеница превращается в куколку, а из куколки выходит бабочка.": "Kapalak tuxum qo‘yadi. Tuxumdan qurt chiqadi. Qurt g‘umbakka aylanadi, g‘umbakdan esa kapalak chiqadi.",
