"← Естествознание 2 класса": "← 2-sinf tabiatshunosligi",
"💡 Балхаш — большое озеро в Казахстане.": "💡 Balxash — Qozog‘istondagi katta ko‘l.",
"💡 Без воды растение не растёт и вянет.": "💡 Suvsiz o‘simlik o‘smaydi va so‘liydi.",
"💡 Без света растение не может нормально расти.": "💡 Yorug‘liksiz o‘simlik me’yorida o‘sa olmaydi.",
"💡 Безопасность важна при любом исследовании.": "💡 Har qanday tadqiqotda xavfsizlik muhim.",
"💡 Белая шерсть сливается со снегом. Хищнику труднее найти зайца.": "💡 Oq mo‘yna qorga qo‘shilib ketadi. Yirtqichga quyonni topish qiyinroq.",
"💡 Береги природу и не обижай животных.": "💡 Tabiatni asra va hayvonlarni xafa qilma.",
"💡 Береги то, что растёт: сажай, поливай, не ломай.": "💡 O‘sayotgan narsani asra: ek, sug‘or, sindirma.",
"💡 Благодаря Солнцу на Земле тепло и светло, и растут растения.": "💡 Quyosh tufayli Yerda iliq va yorug‘, o‘simliklar o‘sadi.",
"💡 Больные молочные зубы могут испортить и постоянные. Чистить надо всегда.": "💡 Kasal sut tishlari doimiy tishlarni ham buzishi mumkin. Tishlarni doim yuvish kerak.",
"💡 Браконьеры убивают животных, а без леса животным негде жить.": "💡 Brakonyerlar hayvonlarni o‘ldiradi, o‘rmonsiz esa hayvonlarning yashashga joyi yo‘q.",
"💡 Бумагу делают из древесины. Это растительный ресурс.": "💡 Qog‘oz yog‘ochdan tayyorlanadi. Bu o‘simlik resursi.",
"💡 В Красную книгу записывают тех, кому грозит исчезновение.": "💡 Qizil kitobga yo‘qolib ketish xavfi ostidagilar yoziladi.",
"💡 В Красную книгу записывают тех, кто может исчезнуть. Их охраняют.": "💡 Qizil kitobga yo‘qolib ketishi mumkin bo‘lganlar yoziladi. Ular muhofaza qilinadi.",
"💡 В воздухе есть кислород. Он нужен для дыхания.": "💡 Havoda kislorod bor. U nafas olish uchun kerak.",
"💡 В году 12 месяцев.": "💡 Yilda 12 oy bor.",
"💡 В горбах у верблюда запас жира. Поэтому он долго живёт без еды.": "💡 Tuyaning o‘rkachlarida yog‘ zaxirasi bor. Shuning uchun u ovqatsiz uzoq yashaydi.",
"💡 В заповеднике запрещена охота. Здесь сохраняют природу.": "💡 Qo‘riqxonada ov qilish taqiqlangan. Bu yerda tabiat saqlanadi.",
"💡 В комнате обычно около 20 градусов тепла.": "💡 Xonada odatda taxminan 20 daraja issiq bo‘ladi.",
"💡 В конце сравниваем записи и делаем вывод.": "💡 Oxirida yozuvlarni solishtiramiz va xulosa chiqaramiz.",
"💡 В музеях хранят и показывают настоящие предметы и коллекции.": "💡 Muzeylarda haqiqiy buyumlar va to‘plamlar saqlanadi va ko‘rsatiladi.",
"💡 В научно-популярной книге есть проверенные сведения.": "💡 Ilmiy-ommabop kitobda tekshirilgan ma’lumotlar bor.",
"💡 В неделе 7 суток.": "💡 Haftada 7 sutka bor.",
"💡 В плодах развиваются семена.": "💡 Urug‘lar mevalarda rivojlanadi.",
"💡 В почве есть перегной — остатки растений и животных. Он делает её плодородной.": "💡 Tuproqda chirindi bor — o‘simliklar va hayvonlarning qoldiqlari. U tuproqni unumdor qiladi.",
"💡 В природе всё связано. Если исчезает один вид, страдают и другие.": "💡 Tabiatda hamma narsa bog‘liq. Bir tur yo‘qolsa, boshqalar ham zarar ko‘radi.",
"💡 В пустыне воды мало, и корни уходят глубоко за ней.": "💡 Cho‘lda suv kam, ildizlar uni izlab chuqur ketadi.",
"💡 В стакане есть воздух, и он занимает место.": "💡 Stakanda havo bor va u joy egallaydi.",
"💡 В суставах кости соединяются. Колено и локоть — суставы.": "💡 Bo‘g‘imlarda suyaklar birlashadi. Tizza va tirsak — bo‘g‘imlar.",
"💡 В сутках 24 часа, а значит сутки больше.": "💡 Sutkada 24 soat bor, demak sutka uzunroq.",
"💡 В сутках 24 часа.": "💡 Sutkada 24 soat bor.",
"💡 В тёплых краях зимой есть корм.": "💡 Iliq o‘lkalarda qishda ozuqa bor.",
"💡 В часе 60 минут.": "💡 Soatda 60 daqiqa bor.",
"💡 В эксперименте мы сами что-то делаем и смотрим, что получится.": "💡 Tajribada biz o‘zimiz nimadir qilamiz va nima chiqishini ko‘ramiz.",
"💡 Верблюжья колючка выдерживает жару и сухость.": "💡 Yantoq issiq va quruqlikka chidaydi.",
"💡 Весной тепло и появляется вода: почки раскрываются.": "💡 Bahorda issiq bo‘ladi va suv paydo bo‘ladi: kurtaklar ochiladi.",
"💡 Весной трава начинает расти заново.": "💡 Bahorda o‘t yana o‘sa boshlaydi.",
"💡 Ветер толкает парус. Сила ветра двигает лодку.": "💡 Shamol yelkanni turtadi. Shamol kuchi qayiqni harakatga keltiradi.",
"💡 Взрослый поможет найти надёжный сайт и не попасть на опасный.": "💡 Kattalar ishonchli saytni topishga va xavfli saytga tushib qolmaslikka yordam beradi.",
"💡 Внимательность помогает увидеть то, что другие пропустят.": "💡 Diqqatlilik boshqalar o‘tkazib yuboradigan narsani ko‘rishga yordam beradi.",
"💡 Вода кипит при 100 градусах.": "💡 Suv 100 darajada qaynaydi.",
"💡 Вода не заполняет стакан, потому что там воздух.": "💡 Suv stakanni to‘ldirmaydi, chunki unda havo bor.",
"💡 Вода переливается и течёт.": "💡 Suvni quyish mumkin va u oqadi.",
"💡 Вода превращается в пар и уходит в воздух.": "💡 Suv bug‘ga aylanib, havoga ketadi.",
"💡 Вода принимает форму сосуда, поэтому форма изменилась.": "💡 Suv idishning shaklini oladi, shuning uchun shakl o‘zgardi.",
"💡 Вода принимает форму сосуда.": "💡 Suv idishning shaklini oladi.",
"💡 Воду растение берёт корнями.": "💡 O‘simlik suvni ildizlari bilan oladi.",
"💡 Водяной пар — вода в виде газа.": "💡 Suv bug‘i — gaz holatidagi suv.",
"💡 Воздух есть везде: даже в «пустом» стакане.": "💡 Havo hamma joyda bor: hatto «bo‘sh» stakanda ham.",
"💡 Воздух заполняет шарик и распирает его изнутри.": "💡 Havo sharchani to‘ldiradi va uni ichidan kerib turadi.",
"💡 Воздух между волосками удерживает тепло тела.": "💡 Tuklar orasidagi havo tananing issiqligini ushlab turadi.",
"💡 Воздух между перьями — тёплая «подушка».": "💡 Patlar orasidagi havo — issiq «yostiq».",
"💡 Воздух плохо проводит тепло. Двойные окна сохраняют тепло.": "💡 Havo issiqlikni yomon o‘tkazadi. Qo‘sh oynalar issiqlikni saqlaydi.",
