"💡 Прозрачное стекло хорошо пропускает свет.": "💡 Shaffof shisha yorug‘likni yaxshi o‘tkazadi.",
"💡 Прозрачные предметы пропускают свет, и сквозь них всё видно.": "💡 Shaffof buyumlar yorug‘likni o‘tkazadi va ular orqali hamma narsa ko‘rinadi.",
"💡 Прямая спина помогает беречь осанку.": "💡 Tik orqa qad-qomatni asrashga yordam beradi.",
"💡 Птицы греют птенцов и приносят им корм.": "💡 Qushlar polaponlarni isitadi va ularga ozuqa olib keladi.",
"💡 Птицы откладывают яйца. Из яиц вылупляются птенцы.": "💡 Qushlar tuxum qo‘yadi. Tuxumlardan polaponlar chiqadi.",
"💡 Птицы строят гнёзда и откладывают в них яйца.": "💡 Qushlar uya quradi va unga tuxum qo‘yadi.",
"💡 Пчёлы и бабочки переносят пыльцу. Без них было бы меньше плодов.": "💡 Asalarilar va kapalaklar gulchang tashiydi. Ularsiz mevalar kamroq bo‘lardi.",
"💡 Ракета развивает огромную скорость.": "💡 Raketa katta tezlikka erishadi.",
"💡 Растения дышат: воздух нужен листьям, корням и семенам.": "💡 O‘simliklar nafas oladi: havo barglar, ildizlar va urug‘lar uchun kerak.",
"💡 Редких цветов осталось мало. Их нужно беречь.": "💡 Noyob gullar oz qolgan. Ularni asrash kerak.",
"💡 Результат — то, что мы увидели и узнали.": "💡 Natija — biz ko‘rgan va bilib olgan narsa.",
"💡 Результаты опыта удобно записывать в таблицу.": "💡 Tajriba natijalarini jadvalga yozish qulay.",
"💡 Ресурсы — приборы и материалы для опыта.": "💡 Resurslar — tajriba uchun asboblar va materiallar.",
"💡 Родник — это место, где подземная вода выходит на поверхность.": "💡 Buloq — yer osti suvi yer yuziga chiqadigan joy.",
"💡 Руды и нефть добывают из земли — это минеральные ресурсы.": "💡 Rudalar va neft yerdan qazib olinadi — bular mineral resurslar.",
"💡 Рыбы дышат жабрами и плавают с помощью плавников.": "💡 Baliqlar jabralari bilan nafas oladi va qanotchalari yordamida suzadi.",
"💡 Рыбы откладывают в воду много икринок. Из них появляются мальки.": "💡 Baliqlar suvga ko‘p ikra qo‘yadi. Ulardan chavoqlar chiqadi.",
"💡 Рыхление, полив и удобрение помогают почве оставаться плодородной.": "💡 Yumshatish, sug‘orish va o‘g‘itlash tuproqning unumdor bo‘lib qolishiga yordam beradi.",
"💡 Рёбра образуют грудную клетку. Внутри неё сердце и лёгкие.": "💡 Qovurg‘alar ko‘krak qafasini hosil qiladi. Uning ichida yurak va o‘pka bor.",
"💡 Рёв самолёта очень громкий и вредный для слуха.": "💡 Samolyotning gumburlashi juda baland va eshitish uchun zararli.",
"💡 С чистыми руками на тело не попадают микробы.": "💡 Qo‘llar toza bo‘lsa, mikroblar tanaga tushmaydi.",
"💡 Самолёт летит быстрее поезда.": "💡 Samolyot poyezdga qaraganda tezroq uchadi.",
"💡 Сахар в воде исчезает: он растворяется.": "💡 Shakar suvda yo‘qoladi: u eriydi.",
"💡 Сахар растворился и придал воде вкус.": "💡 Shakar erib, suvga ta’m berdi.",
"💡 Свет не проходит через непрозрачный предмет. За ним образуется тень.": "💡 Yorug‘lik shaffof bo‘lmagan buyumdan o‘tmaydi. Uning orqasida soya hosil bo‘ladi.",
"💡 Свет нужен листьям для питания.": "💡 Barglarga oziqlanish uchun yorug‘lik kerak.",
"💡 Свет нужен растению для роста.": "💡 O‘simlikka o‘sish uchun yorug‘lik kerak.",
"💡 Семена отдыхают, весной они прорастут.": "💡 Urug‘lar dam olyapti, bahorda unib chiqadi.",
"💡 Семя прорастает, когда есть влага, тепло и воздух.": "💡 Urug‘ namlik, issiqlik va havo bo‘lganda unib chiqadi.",
"💡 Сквозь полупрозрачные предметы проходит свет, но предметы видны неясно.": "💡 Yarim shaffof buyumlar orqali yorug‘lik o‘tadi, lekin buyumlar noaniq ko‘rinadi.",
