"💡 Скорость говорит о том, быстро или медленно движется тело.": "💡 Tezlik jism tez yoki sekin harakatlanayotganini bildiradi.",
"💡 Сладкое вредит зубам. После сладкого лучше прополоскать рот.": "💡 Shirinlik tishlarga zarar qiladi. Shirinlikdan keyin og‘izni chayqagan yaxshi.",
"💡 Слух нужно беречь с детства.": "💡 Eshitishni bolalikdan asrash kerak.",
