"Поздравляю! Ты узнал про правила безопасности, устройства ввода и вывода, файлы и папки, поиск в сети, клавиатуру, алгоритмы, Scratch, редактирование рисунка и звука и про роботов. Теперь закрепи знания в играх.": "Tabriklayman! Sen xavfsizlik qoidalari, kiritish va chiqarish qurilmalari, fayllar va papkalar, tarmoqda qidiruv, klaviatura, algoritmlar, Scratch, rasm va tovushni tahrirlash hamda robotlar haqida bilib oldin. Endi bilimlaringni o‘yinlarda mustahkamla.",
