"Что выполнит исполнитель?: Алгоритм: если светофор красный — стоять, иначе — идти. Светофор зелёный. Что делает исполнитель?": "Ijrochi nimani bajaradi?: Algoritm: agar svetofor qizil bo‘lsa — tur, aks holda — yur. Svetofor yashil. Ijrochi nima qiladi?",
